/// <summary>The four rules of the V6 massage as the plan would be given them, and the types they are written over.</summary>
public abstract class ShapedBase
{
	public int Id { get; protected set; }
	public DateTime Created { get; protected set; }
	public string? Title { get; protected set; }
	public decimal Price { get; protected set; }
	public int? Qty { get; protected set; }
	public bool IsActive { get; protected set; }
	public Guid Key { get; protected set; }
	public double Score { get; protected set; }
	public string? Note { get; protected set; }
	public byte[]? Blob { get; protected set; }
	public long Big { get; protected set; }
	public string? Body { get; protected set; }
	public decimal? Amount { get; protected set; }
	public DateTime? Stamp { get; protected set; }
	public string? Tag { get; protected set; }
	public double Ratio { get; protected set; }
	public bool? Flag { get; protected set; }
	public Guid? Link { get; protected set; }
	public long Count { get; protected set; }
	public string? Summary { get; protected set; }

	public SynItem ToItem() => new()
	{
		Id = Id,
		Created = Created,
		Title = Title,
		Price = Price,
		Qty = Qty,
		IsActive = IsActive,
		Key = Key,
		Score = Score,
		Note = Note,
		Blob = Blob,
		Big = Big,
		Body = Body,
		Amount = Amount,
		Stamp = Stamp,
		Tag = Tag,
		Ratio = Ratio,
		Flag = Flag,
		Link = Link,
		Count = Count,
		Summary = Summary,
	};
}

/// <summary>V6b-K at width 1: the one public constructor of the plan's constructor path; the massage is its body.</summary>
public sealed class Shaped1 : ShapedBase
{
