	internal static SynRow ReadD1(DbDataReader r)
	{
		int index = -1;
		try
		{
			var x = new SynRow();
			index = 0;
			if (!r.IsDBNull(0)) x.Id = r.GetInt32(0);
			return x;
		}
		catch (Exception ex) when (ex is not (DbException or OperationCanceledException))
		{
			throw MapError(ex, index);
		}
	}

