	/// <summary>V6b-K: <c>Map&lt;ShapedN&gt;().ToList()</c> for the width (a static delegate, resolved once per case).</summary>
	public static Func<SyntheticConnection, IList> K(int width) => width switch
	{
		1 => static c => c.Command(Sql).Map<Shaped1>().ToList(),
		3 => static c => c.Command(Sql).Map<Shaped3>().ToList(),
		5 => static c => c.Command(Sql).Map<Shaped5>().ToList(),
		10 => static c => c.Command(Sql).Map<Shaped10>().ToList(),
		20 => static c => c.Command(Sql).Map<Shaped20>().ToList(),
		_ => throw new ArgumentOutOfRangeException(nameof(width), WidthMessage),
	};
}

